const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const houston = ee.Geometry.Point([-95.3698, 29.7604]); // Approximate center of Houston
  const analysisRegion = houston.buffer(5000); // 5 km buffer around Houston

  const april2024Start = '2024-04-01';
  const april2024End = '2024-04-30';
  const may18_2024Start = '2024-05-18';
  const may18_2024End = '2024-05-18';

  const scale = 1000; // Resolution in meters for reduceRegion

  // 2. Data Acquisition & Check for April 2024 (Monthly Average)
  let aprilCollection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterDate(april2024Start, april2024End)
    .filterBounds(analysisRegion);

  const aprilCount = aprilCollection.size().getInfo();
  console.log(`April 2024 Monthly Images: ${aprilCount}`);

  if (aprilCount === 0) {
    console.log("No monthly VIIRS DNB data found for April 2024.");
    console.log("C1");
    return;
  }

  // Calculate average intensity for April 2024
  let aprilAvgRad = aprilCollection.select('avg_rad').mean();
  let aprilStats = aprilAvgRad.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: analysisRegion,
    scale: scale,
    maxPixels: 1e9,
  });

  let aprilIntensity = aprilStats.get('avg_rad').getInfo();

  if (aprilIntensity === null || isNaN(aprilIntensity)) {
    console.log("Calculation of April 2024 average intensity failed or resulted in null/NaN.");
    console.log("C3");
    return;
  }

  // 3. Data Acquisition & Check for May 18, 2024 (Daily Intensity)
  let mayCollection = ee.ImageCollection('NOAA/VIIRS/DNB/VCMCFG_V1') // VCMCFG_V1 for daily
    .filterDate(may18_2024Start, may18_2024End)
    .filterBounds(analysisRegion)
    .filter(ee.Filter.eq('daynight', 'night')); // Ensure we get nighttime data

  const mayCount = mayCollection.size().getInfo();
  console.log(`May 18, 2024 Daily Images: ${mayCount}`);

  if (mayCount === 0) {
    console.log("No daily VIIRS DNB data found for May 18, 2024.");
    console.log("C1");
    return;
  }

  // Calculate intensity for May 18, 2024 (mean of radiance if multiple images, or single image)
  let may18Image = mayCollection.select('radiance').mean(); // Take mean of radiance for the day
  let may18Stats = may18Image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: analysisRegion,
    scale: scale,
    maxPixels: 1e9,
  });

  let may18Intensity = may18Stats.get('radiance').getInfo();

  if (may18Intensity === null || isNaN(may18Intensity)) {
    console.log("Calculation of May 18, 2024 intensity failed or resulted in null/NaN.");
    console.log("C3");
    return;
  }

  // Check for valid pixels (This is implicitly handled if intensity is not null/NaN and > 0, but can be explicit)
  const aprilPixelCount = aprilAvgRad.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: analysisRegion,
    scale: scale,
    maxPixels: 1e9,
  }).get('avg_rad').getInfo();

  const mayPixelCount = may18Image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: analysisRegion,
    scale: scale,
    maxPixels: 1e9,
  }).get('radiance').getInfo();

  if (aprilPixelCount === 0 || mayPixelCount === 0) {
    console.log("No valid pixels remain after processing for one or both periods.");
    console.log("C2");
    return;
  }

  // 4. Comparison and Final Answer
  console.log(`April 2024 Average Intensity: ${aprilIntensity.toFixed(4)} nW/cm²/sr`);
  console.log(`May 18, 2024 Intensity: ${may18Intensity.toFixed(4)} nW/cm²/sr`);
  console.log(`April Pixels: ${aprilPixelCount}, May Pixels: ${mayPixelCount}`);

  if (may18Intensity < aprilIntensity) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
